"""Deterministic code generation from the Visual IR.

Emitters are pure functions of the IR: the same IR always produces the same
output. Generated files state which parts were observed and which were inferred,
so nobody mistakes reconstruction for recovered source.
"""

from __future__ import annotations

import html as html_lib
from typing import Dict, List

from .ir import NodeIR, VisualIR

VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}

FIDELITY_NOTE = (
    "Generated by ProtectREVERSE from observed markup and CSS. "
    "Structure, class names and token values are observed. "
    "Component naming, section semantics and any interaction logic are inferred."
)


def _attrs(node: NodeIR) -> str:
    parts: List[str] = []
    for key in sorted(node.attrs):
        if key.startswith("__"):
            continue
        value = node.attrs[key].strip()
        if not value and key != "alt":
            continue
        parts.append(f'{key}="{html_lib.escape(value, quote=True)}"')
    return (" " + " ".join(parts)) if parts else ""


def _render(node: NodeIR, depth: int) -> List[str]:
    pad = "  " * depth
    if node.tag == "#document":
        lines: List[str] = []
        for child in node.children:
            lines.extend(_render(child, depth))
        return lines

    if node.tag in VOID_TAGS:
        return [f"{pad}<{node.tag}{_attrs(node)}>"]

    if not node.children:
        text = html_lib.escape(node.text)
        return [f"{pad}<{node.tag}{_attrs(node)}>{text}</{node.tag}>"]

    lines = [f"{pad}<{node.tag}{_attrs(node)}>"]
    if node.text:
        lines.append(f"{pad}  {html_lib.escape(node.text)}")
    for child in node.children:
        lines.extend(_render(child, depth + 1))
    lines.append(f"{pad}</{node.tag}>")
    return lines


def to_html(ir: VisualIR, page_index: int = 0) -> str:
    page = ir.pages[page_index]
    body = _render(page.root, 0)
    header = [
        "<!doctype html>",
        f"<!-- {FIDELITY_NOTE} -->",
    ]
    return "\n".join(header + body) + "\n"


def _declarations(declarations: Dict[str, str], indent: str) -> List[str]:
    return [f"{indent}{prop}: {value};" for prop, value in declarations.items()]


def _rule(rule, indent: str = "") -> List[str]:
    lines = [f"{indent}{rule.selector} {{"]
    lines.extend(_declarations(rule.declarations, indent + "  "))
    lines.append(f"{indent}}}")
    return lines


def to_css(ir: VisualIR) -> str:
    lines: List[str] = [f"/* {FIDELITY_NOTE} */", ""]

    custom = ir.tokens_of("custom")
    derived = [t for t in ir.tokens if t.kind != "custom"]
    if custom or derived:
        lines.append(":root {")
        for token in custom:
            lines.append(f"  {token.name}: {token.value};")
        for token in derived:
            lines.append(f"  --ds-{token.name}: {token.value}; /* {token.usage} use(s) */")
        lines.append("}")
        lines.append("")

    plain = [r for r in ir.rules if not r.media]
    grouped: Dict[str, List] = {}
    for rule in ir.rules:
        if rule.media:
            grouped.setdefault(rule.media, []).append(rule)

    for rule in plain:
        lines.extend(_rule(rule))
        lines.append("")

    for media in sorted(grouped):
        lines.append(f"@media {media} {{")
        for rule in grouped[media]:
            lines.extend(_rule(rule, "  "))
        lines.append("}")
        lines.append("")

    return "\n".join(lines).rstrip() + "\n"
